    // ---- System B: the faction vulnerability column ----------------------
    // Keyed by `FactionDamageOverride ?? Faction`, per COMPONENT, and chosen
    // by the POOL the damage lands on (docs/MECHANICS.md §8).

    /// The infinite dummy, wearing one faction's column.
    fn column_dummy(key: &str, overguard: f64) -> TargetParams {
        TargetParams {
            type_mods: crate::factions_data::columns_for(key),
            ..frail_target(TargetMode::InfiniteHealth, 0.0, overguard)
        }
    }

    /// One run's effective damage from a fixed vector against one column.
    fn eff_vs(key: &str, v: DamageVector) -> f64 {
        let p = DummyParams {
            damage: v,
            crit_multiplier: 1.0,
            base_crit_chance: 0.0,
            arcane: ArcaneFx::none(),
            body_parts: mono_body(1.0),
            target: column_dummy(key, 0.0),
            ..no_status()
        };
        monte_carlo(&p, 20, 3).mean_effective_damage
    }

    #[test]
    fn the_vulnerability_column_scales_each_component_on_its_own() {
        let impact = DamageVector::new().with(DamageType::Impact, 100.0);
        let neutral = eff_vs("unknown", impact);
        assert!(neutral > 0.0);

        // Grineer: Impact ×1.5 (and Corrosive, which this hit has none of).
        assert!(
            (eff_vs("grineer", impact) - neutral * 1.5).abs() < 1e-6,
            "grineer impact {}",
            eff_vs("grineer", impact)
        );
        // A RESISTANCE is the same mechanism pointing down.
        let rad = DamageVector::new().with(DamageType::Radiation, 100.0);
        assert!(
            (eff_vs("orokin", rad) - eff_vs("unknown", rad) * 0.5).abs() < 1e-6,
            "orokin radiation"
        );
        // Per COMPONENT, not per hit: half a vector at ×1.5 is ×1.25 overall.
        // This is the "dilution" the wiki means — compositional, not a bucket.
        let mixed = DamageVector::new()
            .with(DamageType::Impact, 50.0)
            .with(DamageType::Slash, 50.0);
        assert!(
            (eff_vs("grineer", mixed) - eff_vs("unknown", mixed) * 1.25).abs() < 1e-6,
            "mixed {} vs {}",
            eff_vs("grineer", mixed),
            eff_vs("unknown", mixed)
        );
        // A faction with nothing to say about this type changes nothing.
        assert!((eff_vs("stalker", impact) - neutral).abs() < 1e-9);
    }

    /// The damage-by-type breakdown is what a reader consults to decide what
    /// to add next, so it splits by what each component actually DID.
    #[test]
    fn the_by_type_breakdown_follows_the_column_too() {
        let v = DamageVector::new()
            .with(DamageType::Impact, 50.0)
            .with(DamageType::Slash, 50.0);
        let grineer = crate::factions_data::column("grineer");
        let mut dst = [0.0f64; DamageType::ALL.len()];
        // 125 effective is what 50 Impact ×1.5 + 50 Slash ×1.0 comes to.
        add_by_type(&mut dst, &v, 125.0, &grineer);
        assert!((dst[DamageType::Impact as usize] - 75.0).abs() < 1e-9, "{dst:?}");
        assert!((dst[DamageType::Slash as usize] - 50.0).abs() < 1e-9, "{dst:?}");
        // Neutral: the plain proportional split it always was.
        let mut flat = [0.0f64; DamageType::ALL.len()];
        add_by_type(&mut flat, &v, 100.0, &crate::factions_data::Column::NEUTRAL);
        assert!((flat[DamageType::Impact as usize] - 50.0).abs() < 1e-9);
    }

    /// Overguard is a LAYER over the unit, with its own table — the unit's
    /// column must not reach it, and Void must.
    #[test]
    fn overguard_reads_its_own_column_not_the_units() {
        let shot = |key: &str, t: DamageType| {
            let p = DummyParams {
                damage: DamageVector::new().with(t, 100.0),
                crit_multiplier: 1.0,
                base_crit_chance: 0.0,
                arcane: ArcaneFx::none(),
                body_parts: mono_body(1.0),
                target: column_dummy(key, 1e12),
                ..no_status()
            };
            monte_carlo(&p, 20, 3).mean_effective_damage
        };
        let base = shot("unknown", DamageType::Impact);
        // Grineer's Impact ×1.5 stops at the overguard layer.
        assert!((shot("grineer", DamageType::Impact) - base).abs() < 1e-9);
        // Void ×1.5 is the Overguard column's own entry, on any unit.
        assert!((shot("grineer", DamageType::Void) - base * 1.5).abs() < 1e-6);
        assert!((shot("unknown", DamageType::Void) - base * 1.5).abs() < 1e-6);
    }

    /// Bleed is stored under Slash — the proc that made it — but the damage is
    /// CINEMATIC, which takes no faction modifier anywhere. An Infested target
    /// (Slash ×1.5) must boost the HIT and not the bleed it leaves.
    #[test]
    fn bleed_takes_no_faction_modifier_though_it_is_filed_under_slash() {
        let run = |key: &str| {
            let p = DummyParams {
                damage: DamageVector::new().with(DamageType::Slash, 100.0),
                target: column_dummy(key, 0.0),
                ..bare(DamageType::Slash)
            };
            let s = monte_carlo(&p, 20, 3);
            (s.mean_effective_damage - s.mean_dot_damage, s.mean_dot_damage)
        };
        let (direct_n, dot_n) = run("unknown");
        let (direct_i, dot_i) = run("infested");
        assert!(dot_n > 0.0 && direct_n > 0.0, "the fixture must do both");
        // The direct Slash hit takes the column…
        assert!(
            (direct_i - direct_n * 1.5).abs() < 1e-6,
            "direct {direct_i} vs {direct_n}"
        );
        // …and the bleed it leaves does not.
        assert!((dot_i - dot_n).abs() < 1e-9, "dot {dot_i} vs {dot_n}");
    }

    /// The column and Toxin's shield bypass are two readings of ONE shape:
    /// the Toxin part is scaled by Toxin's factor on its way past the shield,
    /// the rest by theirs on the way into it.
    #[test]
    fn the_column_follows_each_component_into_the_pool_it_lands_in() {
        // Narmer: Toxin ×1.5, Magnetic ×0.5. Seven shots of 16 Toxin + 16
        // Magnetic into a shield that never breaks and 160 health:
        //   neutral  7 × 16       = 112  -> alive
        //   narmer   7 × 16 × 1.5 = 168  -> dead
        // The Magnetic half never reaches health under either column.
        let kills = |key: &str| {
            let p = DummyParams {
                damage: DamageVector::new()
                    .with(DamageType::Toxin, 16.0)
                    .with(DamageType::Magnetic, 16.0),
                crit_multiplier: 1.0,
                base_crit_chance: 0.0,
                arcane: ArcaneFx::none(),
                body_parts: mono_body(1.0),
                fire_rate: 10.0,
                duration_seconds: 0.65,
                magazine_size: 100.0,
                target: TargetParams {
                    type_mods: crate::factions_data::columns_for(key),
                    base_shield: 10_000.0,
                    base_health: 160.0,
                    ..frail_target(TargetMode::InstantRespawn, 0.0, 0.0)
                },
                ..no_status()
            };
            monte_carlo(&p, 20, 5).mean_kills
        };
        assert_eq!(kills("unknown"), 0.0, "112 damage must not kill 160 health");
        assert_eq!(kills("narmer"), 1.0, "Toxin x1.5 past the shield kills it");
    }

    #[test]
    fn toxin_dot_matches_the_bleed_shape_at_half_base() {
        // Toxin mirrors the forced-bleed test at coefficient 0.5 vs 0.35:
        // 39 ticks × 37.5 = 1462.5 (no armor: full value).
        let s = monte_carlo(&bare(DamageType::Toxin), 20, 5);
        assert!(
            (s.mean_dot_damage - 1462.5).abs() < 1e-9,
            "dot {}",
            s.mean_dot_damage
        );
    }

    /// M54: A BLAST AoE CARRIES THE WEAK POINT AND A TOXIN DoT DOES NOT.
    ///
    /// Two rules that sound like one and go opposite ways, both measured in
    /// game on the same afternoon (owner, 2026-08-22). The blast half is the
    /// sharp one because the numbers came back exact:
    ///
    /// | 10 stacks applied by | a neighbour takes |
    /// | --- | --- |
    /// | body hits, no crits | 1050 |
    /// | head hits, no crits | 3150 |
    ///
    /// `3150 / 1050 = 3.000`, which is the head multiplier and nothing else.
    /// This asserts the RATIO rather than either number, so it holds whatever
    /// the build is.
    #[test]
    fn a_blast_aoe_carries_the_weak_point_and_a_toxin_dot_does_not() {
        // ---- the blast half: the AoE a body detonation posts, head vs body.
        //
        // Driven through `settle_procs`' own scale rather than a fixture, so it
        // is the production path that is being measured.
        let aoe = |part_factor: f64| {
            let mut d = DebuffState::default();
            for _ in 0..TEN_STACK_CAP {
                d.blast.push(BlastStack {
                    fuse: 99.0,
                    value: BLAST_COEFFICIENT * 1000.0 * part_factor,
                    xh_bracket: 1.0,
                });
            }
            // `on_death` is the OTHER trigger the wiki names -- "10 stacks OR
            // the target dying" -- and it posts the same radial the tenth stack
            // would, which is the cheap way to read it here.
            d.on_death(None, &frail_target(TargetMode::InstantRespawn, 0.0, 0.0));
            d.area_hit.first().map(|h| h.damage).unwrap_or(0.0)
        };
        let body = aoe(1.0);
        let head = aoe(3.0);
        assert!(body > 0.0, "a full pile detonates");
        assert!(
            (head / body - 3.0).abs() < 1e-9,
            "M54: a head-applied pile reaches a neighbour at exactly x3 — \
             measured 3150 / 1050 = 3.000, got {head} / {body}"
        );
        // …AND THE 10x BETWEEN THE TWO HALVES. Ten stacks are 300% each to the
        // neighbours against 30% each to the host: `1050 / 10.5 = 100` over ten
        // stacks, i.e. ten times the host's own total.
        let host: f64 = TEN_STACK_CAP as f64 * BLAST_COEFFICIENT * 1000.0;
        assert!(
            (body / host - 10.0).abs() < 1e-9,
            "M54: the radial is 10x the single-target total — got {}",
            body / host
        );

        // ---- the toxin half, which goes the OTHER way.
        assert!(!dot_takes_weakpoint(DamageType::Toxin), "M54: measured in game");
        // The rest are UNMEASURED and keep the wiki's answer. Asserted so that
        // extending the rule to them is a deliberate edit rather than a drift.
        for t in [
            DamageType::Slash,
            DamageType::Electricity,
            DamageType::Gas,
            DamageType::Heat,
        ] {
            assert!(dot_takes_weakpoint(t), "{t:?} is unmeasured and keeps the wiki's answer");
        }
    }

    /// A CONSOLIDATED FAMILY PAYS ONCE, and the HEAP path pays the same as the
    /// scan.
    ///
    /// `process_ticks` has two ways of asking for the next event — a linear
    /// SCAN under `TICK_QUEUE_MIN` live DoTs and a heap over it. The merge
    /// advances EVERY live instance of a family when the first of them fires,
    /// which leaves keys in the heap for ticks already paid; the scan can never
    /// produce one, because it reads `next_tick` live. Without the guard that
    /// skips them a stale key advances its Dot a second time and BURNS a tick,
    /// so the damage comes out LOW rather than double.
    ///
    /// The density is what makes this test worth having: eight forced procs a
    /// shot at 10/s holds hundreds of stacks, well past the 32 that switches
    /// paths. At one proc a shot the fixture never leaves the scan and the
    /// guard is dead code the test cannot see — which is exactly what the first
    /// version of this did, passing identically with the guard removed.
    ///
    /// Measured: 48,000 with the guard, 47,400 without — sixteen burnt ticks.
    /// EVERY DAMAGE SITE POPS A NUMBER, and the log cannot drift from the
    /// curve.
    ///
    /// A `pop` sits beside every `timeline.add` — nine of them — because the
    /// timeline is the AGGREGATE view of exactly the same nine events. So a
    /// tenth damage site added later without a `pop` shows up here as damage
    /// that moved a curve and popped nothing.
    ///
    /// It cannot be an equality: the buffer keeps the twelve BIGGEST numbers a
    /// frame and counts the rest, which is what the game itself does ("a
    /// maximum of 10 tick numbers are shown at once"). So the property is
    /// COVERAGE — every frame that gained damage popped or dropped something —
    /// and it is exact in the direction that matters.
    #[test]
    fn every_frame_that_took_damage_popped_a_number() {
        // A build that exercises several of the nine at once: a direct hit, a
        // crit, a weak point, a Slash bleed and a Heat tick.
        let mut p = DummyParams {
            forced_procs: vec![DamageType::Slash, DamageType::Heat],
            ..bare(DamageType::Slash)
        };
        p.base_crit_chance = 0.5;
        p.crit_multiplier = 2.0;
        let rep = replay(&p, 0, 60);

        let mut frames_with_damage = 0;
        let mut frames_with_pops = 0;
        let mut prev = 0.0;
        for f in &rep.frames {
            let gained = f.damage - prev;
            prev = f.damage;
            if gained <= 1e-9 {
                continue;
            }
            frames_with_damage += 1;
            if !f.pops.is_empty() || f.pops_dropped > 0 {
                frames_with_pops += 1;
            }
        }
        assert!(frames_with_damage > 5, "the fixture deals damage: {frames_with_damage}");
        assert_eq!(
            frames_with_damage, frames_with_pops,
            "{} frames gained damage and {} popped a number — a damage site \
             without a `pop` beside its `timeline.add`",
            frames_with_damage, frames_with_pops
        );

        // …AND THE KINDS ARE TOLD APART. A run with crits, weak points and a
        // DoT must produce more than one kind, or the classifier is a constant.
        let kinds: std::collections::BTreeSet<PopKind> =
            rep.frames.iter().flat_map(|f| f.pops.iter().map(|p| p.kind)).collect();
        assert!(kinds.len() >= 2, "a fight has more than one kind of number: {kinds:?}");
        assert!(
            kinds.contains(&PopKind::Status),
            "a Slash bleed and a Heat tick are statuses: {kinds:?}"
        );

        // …AND NOTHING POPS WHEN NOBODY IS WATCHING. The collector is off for
        // the 999 runs that are summed and thrown away, which is what keeps it
        // free — asserted because "it is only on while tracing" is exactly the
        // kind of claim that quietly stops being true.
        let plain = run_once(&p, &mut Rng::new(0));
        assert!(!plain.pops_on, "an untraced run collects nothing");
    }

    #[test]
    fn a_dense_electricity_fight_pays_each_stack_once() {
        let dense = DummyParams {
            fire_rate: 10.0,
            forced_procs: vec![DamageType::Electricity; 8],
            ..bare(DamageType::Electricity)
        };
        let s = monte_carlo(&dense, 20, 5);
        assert!(
            (s.mean_dot_damage - 48_000.0).abs() < 1e-9,
            "dot {} — 47,400 is the answer with the stale-key guard removed",
            s.mean_dot_damage
        );
    }

    #[test]
    fn electricity_joins_one_clock_per_body() {
        // THE GOLDEN MOVED BECAUSE THE MECHANIC DID, and the citation is dated:
        // wiki `Damage/Electricity Damage`, Update 33.6 — "multiple procs on an
        // enemy no longer deal their respective damage separately, like current
        // Slash statuses, but once per second, similar to Heat status. However,
        // they still maintain each own timer and will not refresh, unlike Heat."
        // The owner saw the same thing in game on 2026-08-22: one number, and
        // its cadence stays with the first proc.
        //
        // This test used to be `electricity_dot_ticks_immediately` and asserted
        // the PRE-33.6 model — shot at k ticking at k..k+5, so
        // 6+6+6+6+6+5+4+3+2+1 = 45 ticks × 37.5 = 1687.5.
        //
        // Under one clock the first proc still ticks at 0 (there is no clock to
        // join yet) and every later one waits for the shared tick, which this
        // cadence puts exactly one second ahead: shot at k ticks at k+1..k+6.
        // Before 10 s that is 6+6+6+6+5+4+3+2+1+0 = 39 ticks × 37.5 = 1462.5.
        //
        // IT IS NOT A 13% NERF TO ELECTRICITY. The six ticks are not lost, they
        // are past the ten-second window this fixture counts in — every
        // instance still pays its full six. What a real engagement loses is the
        // tail of the last few procs, which is the same tail every DoT has.
        let s = monte_carlo(&bare(DamageType::Electricity), 20, 5);
        assert!(
            (s.mean_dot_damage - 39.0 * 37.5).abs() < 1e-9,
            "dot {}",
            s.mean_dot_damage
        );
        // …AND THE INSTANCES ARE STILL THEIR OWN. Heat, whose procs REFRESH
        // each other, answers 1687.5 on this same cadence — so a test that only
        // pinned the total could not tell the two models apart. The difference
        // that matters is that Electricity does not refresh, which is why its
        // number is lower here and Heat's is not.
    }

    #[test]
    fn heat_is_a_single_refreshing_accumulator() {
        // Ten forced Heat procs, one per second: ONE entity born at t=0,
        // each proc adds 37.5 to the tick and refreshes the expiry, ticks
        // anchored at 1,2,...,9 (< 10 s): tick k has k contributions ->
        // Σ k=1..9 of 37.5k = 37.5 × 45 = 1687.5. Same total as the
        // independent-stack Electricity case ONLY by coincidence of this
        // cadence — the entity count differs (1 vs 10).
        let s = monte_carlo(&bare(DamageType::Heat), 20, 5);
        assert!(
            (s.mean_dot_damage - 1687.5).abs() < 1e-9,
            "dot {}",
            s.mean_dot_damage
        );
    }

